async function main() {
  const topBlocks = [
    "892830829d7ffff", // Hayes Valley, 6 reports
    "892830821c7ffff", // Bayview, 2
    "892830821cfffff", // Bayview, 2
    "892830829d7ffff",
    "89283082b8bffff", // Nob Hill
    "8928308285bffff", // SOMA, 143 in 5y
    "8928308299bffff", // GG Park, 112 in 5y
    "89283082963ffff", // Pacific Heights, 101
    "89283082a77ffff", // FiDi/South Beach, 47
  ];
  const seen = new Set<string>();
  const uniq = topBlocks.filter(b => !seen.has(b) && seen.add(b));
  const results = await Promise.all(uniq.map(h3 =>
    tools.mcp_highground_elastic.highground_block_history({ h3 }).then(r => ({ h3, r }))
  ));
  return results;
}
